import static org.junit.Assert.*;

/**
 * Unit tests for ClassUtils.getShortClassName
 */
public class ClassUtils_getShortClassName_TriageGen2Test {

    @Test
    public void testGetShortClassName_Null() {
        assertEquals("", ClassUtils.getShortClassName(null));
    }

    @Test
    public void testGetShortClassName_Empty() {
        assertEquals("", ClassUtils.getShortClassName(""));
    }

    @Test
    public void testGetShortClassName_SimpleClass() {
        // Test a class with no package
        assertEquals("String", ClassUtils.getShortClassName("String"));
        // Test a class with a package
        assertEquals("ArrayList", ClassUtils.getShortClassName("java.util.ArrayList"));
    }

    @Test
    public void testGetShortClassName_InnerClass() {
        // Assuming INNER_CLASS_SEPARATOR_CHAR is '$' based on standard JVM behavior
        // The method replaces inner separator with package separator
        assertEquals("Outer.Inner", ClassUtils.getShortClassName("com.example.Outer$Inner"));
    }

    @Test
    public void testGetShortClassName_ArraySingleDimension() {
        // Test simple array [Ljava.lang.String;
        // Note: The provided code has a bug: className.charAt(-1) will throw IndexOutOfBoundsException.
        // However, I will write the test according to the logic provided.
        // If the code is intended to handle standard JVM array descriptors:
        assertEquals("String[]", ClassUtils.getShortClassName("[Ljava.lang.String;"));
    }

    @Test
    public void testGetShortClassName_ArrayMultiDimension() {
        assertEquals("Integer[][]", ClassUtils.getShortClassName("[[Ljava.lang.Integer;"));
    }

    @Test
    public void testGetShortClassName_PrimitiveArray() {
        assertEquals("int[]", ClassUtils.getShortClassName("[I"));
    }

    @Test
    public void testGetShortClassName_NoPackageWithInnerClass() {
        assertEquals("A.B", ClassUtils.getShortClassName("A$B"));
    }

    /**
     * Note: The provided source code contains a logical error:
     * if (className.charAt(-1) == 'L' ...) 
     * This will always throw StringIndexOutOfBoundsException.
     * I am providing the test case that would trigger that branch.
     */
    @Test(expected = StringIndexOutOfBoundsException.class)
    public void testGetShortClassName_TriggerIndexOutOfBounds() {
        // This triggers the if (className.startsWith("[")) block
        // and then attempts to access charAt(-1)
        ClassUtils.getShortClassName("[Ljava.lang.String;");
    }

    @Test
    public void testGetShortClassName_AbbreviationMap() {
        // This test assumes reverseAbbreviationMap is populated in the real ClassUtils.
        // Since we don't see the implementation of the map, we test the flow.
        // If the map contains "java.lang.String" -> "String", it would be handled.
        // Without access to the private static map, we can only assume standard behavior.
        assertEquals("String", ClassUtils.getShortClassName("java.lang.String"));
    }
}
